pub fn compounds_width(cs: &[Compound]) -> usize {
    cs.iter().map(|c| c.width()).sum()
}

struct Token {
    text: String,
    style: Style,
    blank: bool,
}

fn tokenize(c: &Compound) -> Vec<Token> {
    let mut tokens = Vec::new();
    if c.text.is_empty() {
        return tokens;
    }
    if c.style.code {
        tokens.push(Token { text: c.text.clone(), style: c.style, blank: false });
        return tokens;
    }
    let mut cur = String::new();
    let mut cur_blank: Option<bool> = None;
    for ch in c.text.chars() {
        let b = ch == ' ';
        match cur_blank {
            Some(cb) if cb == b => cur.push(ch),
            Some(cb) => {
                tokens.push(Token { text: std::mem::take(&mut cur), style: c.style, blank: cb });
                cur.push(ch);
                cur_blank = Some(b);
            }
            None => {
                cur.push(ch);
                cur_blank = Some(b);
            }
        }
    }
    if let Some(cb) = cur_blank {
        tokens.push(Token { text: cur, style: c.style, blank: cb });
    }
    tokens
}

/// cut a string so that the first part has at most `width` columns
fn cut_at_width(s: &str, width: usize) -> (String, String) {
    let mut w = 0;
    let mut idx = s.len();
    for (i, ch) in s.char_indices() {
        let cw = char_width(ch);
        if w + cw > width {
            idx = i;
            break;
        }
        w += cw;
    }
    (s[..idx].to_string(), s[idx..].to_string())
}

/// Wrap compounds in lines not wider than `width`
pub fn wrap(cs: &[Compound], width: usize) -> Vec<Vec<Compound>> {
    let total = compounds_width(cs);
    if total <= width {
        return vec![cs.to_vec()];
    }
    let width = width.max(1);
    let mut lines: Vec<Vec<Compound>> = Vec::new();
    let mut cur: Vec<Compound> = Vec::new();
    let mut cur_len = 0usize;
    for c in cs {
        for tok in tokenize(c) {
            let tl = str_width(&tok.text);
            if cur_len + tl <= width {
                cur.push(Compound::new(tok.text, tok.style));
                cur_len += tl;
                continue;
            }
            if tok.blank {
                continue;
            }
            if cur_len > 0 {
                lines.push(std::mem::take(&mut cur));
                cur_len = 0;
            }
            let mut text = tok.text;
            let mut tl = tl;
            while tl > width {
                let (head, tail) = cut_at_width(&text, width);
                if head.is_empty() {
                    break;
                }
                lines.push(vec![Compound::new(head, tok.style)]);
                text = tail;
                tl = str_width(&text);
            }
            cur.push(Compound::new(text, tok.style));
            cur_len = tl;
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    if lines.is_empty() {
        lines.push(Vec::new());
    }
    lines
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Align {
    Unspecified,
    Left,
    Center,
    Right,
}

pub struct Table {
    pub aligns: Vec<Align>,
    /// first row is the header
    pub rows: Vec<Vec<Vec<Compound>>>,
}

pub const BORDER_STYLE: Style = Style::fg(239);

impl Table {
    pub fn new(aligns: Vec<Align>) -> Self {
        Table { aligns, rows: Vec::new() }
    }
    pub fn push_row(&mut self, row: Vec<Vec<Compound>>) {
        self.rows.push(row);
    }
    pub fn nb_cols(&self) -> usize {
        self.aligns.len()
    }

    /// compute the widths of the columns so that the table fits the given width
    fn compute_widths(&self, width: usize) -> Vec<usize> {
        let nb_cols = self.nb_cols();
        let nb_rows = self.rows.len().max(1);
        let mut naturals = vec![0usize; nb_cols];
        let mut sums = vec![0usize; nb_cols];
        for row in &self.rows {
            for (i, cell) in row.iter().enumerate().take(nb_cols) {
                let w = compounds_width(cell);
                if w > naturals[i] {
                    naturals[i] = w;
                }
                sums[i] += w;
            }
        }
        let mut widths = naturals.clone();
        let available = width.saturating_sub(nb_cols + 1);
        let sum: usize = widths.iter().sum();
        if sum <= available {
            return widths;
        }
        let mut excess = sum - available;
        // columns sorted by natural width, descending
        let mut order: Vec<usize> = (0..nb_cols).collect();
        order.sort_by(|a, b| naturals[*b].cmp(&naturals[*a]));
        // first phase: reduce the widest columns down to their "average" target
        for &i in &order {
            if excess == 0 {
                break;
            }
            let avg = (sums[i] + nb_rows - 1) / nb_rows;
            let target = avg.max(4).min(naturals[i]);
            if widths[i] > target {
                let r = (widths[i] - target).min(excess);
                widths[i] -= r;
                excess -= r;
            }
        }
        // second phase: reduce down to 3
        for &i in &order {
            if excess == 0 {
                break;
            }
            if widths[i] > 3 {
                let r = (widths[i] - 3).min(excess);
                widths[i] -= r;
                excess -= r;
            }
        }
        widths
    }

    pub fn write(&self, w: &mut Writer, width: usize) {
        if self.rows.is_empty() {
            return;
        }
        let mut widths = self.compute_widths(width);
        // drop columns while the table doesn't fit
        while widths.len() > 1 && widths.iter().sum::<usize>() + widths.len() + 1 > width {
            widths.pop();
        }
        let nb_cols = widths.len();
        self.write_rule(w, &widths, "┌", "┬", "┐");
        for (ri, row) in self.rows.iter().enumerate() {
            let is_header = ri == 0;
            // wrap cells
            let mut cell_lines: Vec<Vec<Vec<Compound>>> = Vec::new();
            let mut height = 1;
            for ci in 0..nb_cols {
                let cell: &[Compound] = row.get(ci).map(|c| c.as_slice()).unwrap_or(&[]);
                let lines = wrap(cell, widths[ci]);
                if lines.len() > height {
                    height = lines.len();
                }
                cell_lines.push(lines);
            }
            for li in 0..height {
                w.write_styled("│", BORDER_STYLE);
                for ci in 0..nb_cols {
                    let align = self.aligns.get(ci).copied().unwrap_or(Align::Unspecified);
                    let align = if is_header {
                        if align == Align::Left { Align::Left } else { Align::Center }
                    } else {
                        align
                    };
                    let empty: Vec<Compound> = Vec::new();
                    let line = cell_lines[ci].get(li).unwrap_or(&empty);
                    let lw = compounds_width(line);
                    let pad = widths[ci].saturating_sub(lw);
                    let (lp, rp) = match align {
                        Align::Right => (pad, 0),
                        Align::Center => (pad / 2, pad - pad / 2),
                        _ => (0, pad),
                    };
                    w.write_str(&" ".repeat(lp));
                    w.write_compounds(line);
                    w.write_str(&" ".repeat(rp));
                    w.write_styled("│", BORDER_STYLE);
                }
                w.newline();
            }
            if is_header {
                self.write_rule(w, &widths, "├", "┼", "┤");
            }
        }
        self.write_rule(w, &widths, "└", "┴", "┘");
    }

    fn write_rule(&self, w: &mut Writer, widths: &[usize], left: &str, mid: &str, right: &str) {
        w.write_styled(left, BORDER_STYLE);
        for (i, cw) in widths.iter().enumerate() {
            if i > 0 {
                w.write_styled(mid, BORDER_STYLE);
            }
            w.write_styled(&"─".repeat(*cw), BORDER_STYLE);
        }
        w.write_styled(right, BORDER_STYLE);
        w.newline();
    }
}
