//! number formatting helpers

/// format an integer with thousands separators
pub fn with_thousands(n: u64) -> String {
    let s = n.to_string();
    let bytes = s.as_bytes();
    let mut out = String::with_capacity(s.len() + s.len() / 3);
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*b as char);
    }
    out
}

/// format a size (in bytes) in at most 4 characters
pub fn fit_4(n: u64) -> String {
    if n < 10_000 {
        return n.to_string();
    }
    let mut f = n as f64;
    for unit in ['K', 'M', 'G', 'T', 'P'] {
        f /= 1000.0;
        if f < 10.0 {
            let s = format!("{:.1}", f);
            if s.len() <= 3 {
                return format!("{}{}", s, unit);
            }
            return format!("{:.0}{}", f, unit);
        }
        let s = format!("{:.0}", f);
        if s.len() <= 3 {
            return format!("{}{}", s, unit);
        }
    }
    "huge".to_string()
}

/// format a percentage with one decimal
pub fn percent1(count: u64, total: u64) -> String {
    if total == 0 {
        return "0.0%".to_string();
    }
    format!("{:.1}%", 100.0 * count as f64 / total as f64)
}

