    use super::*;
    #[test]
    fn test_fit4() {
        assert_eq!(fit_4(0), "0");
        assert_eq!(fit_4(9999), "9999");
        assert_eq!(fit_4(10000), "10K");
        assert_eq!(fit_4(10500), "10K");
        assert_eq!(fit_4(10501), "11K");
        assert_eq!(fit_4(99500), "100K");
        assert_eq!(fit_4(999499), "999K");
        assert_eq!(fit_4(999500), "1.0M");
        assert_eq!(fit_4(1050000), "1.1M");
        assert_eq!(fit_4(1950000), "1.9M");
        assert_eq!(fit_4(9999999), "10M");
        assert_eq!(fit_4(999499999), "999M");
        assert_eq!(fit_4(1000000000000000000), "huge");
        assert_eq!(fit_4(100000000000000000), "100P");
        assert_eq!(with_thousands(1985), "1,985");
        assert_eq!(with_thousands(10000), "10,000");
        assert_eq!(with_thousands(999), "999");
        assert_eq!(with_thousands(1000000), "1,000,000");
    }
}
