    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}/{:02}/{:02}", self.year, self.month, self.day)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct Time {
    pub hour: u8,
    pub minute: u8,
    pub second: u8,
}

impl Time {
    pub fn as_seconds(self) -> u32 {
        self.hour as u32 * 3600 + self.minute as u32 * 60 + self.second as u32
    }
}

impl fmt::Display for Time {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:02}:{:02}:{:02}", self.hour, self.minute, self.second)
    }
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug, Hash)]
pub struct DateTime {
    pub date: Date,
    pub time: Time,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash, PartialOrd, Ord)]
pub enum Method {
    Get,
    Head,
    Post,
    Put,
    Delete,
    Options,
    Connect,
    Patch,
    Trace,
    /// no method (the request couldn't be split)
    None,
    /// any other string
    Other,
}

impl Method {
    pub fn from_str(s: &str) -> Method {
        match s {
            "GET" => Method::Get,
            "HEAD" => Method::Head,
            "POST" => Method::Post,
            "PUT" => Method::Put,
            "DELETE" => Method::Delete,
            "OPTIONS" => Method::Options,
            "CONNECT" => Method::Connect,
            "PATCH" => Method::Patch,
            "TRACE" => Method::Trace,
            "" => Method::None,
            _ => Method::Other,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Method::Get => "GET",
            Method::Head => "HEAD",
            Method::Post => "POST",
            Method::Put => "PUT",
            Method::Delete => "DELETE",
            Method::Options => "OPTIONS",
            Method::Connect => "CONNECT",
            Method::Patch => "PATCH",
            Method::Trace => "TRACE",
            Method::None => "none",
            Method::Other => "other",
        }
    }
}

#[derive(Clone, Debug)]
pub struct LogLine {
    pub remote_addr: String,
    pub date: Date,
    pub time: Time,
    pub method: Method,
    pub path: String,
    pub status: u16,
    pub bytes_sent: u64,
    pub referer: String,
    /// index of the date in the base's date list
    pub date_idx: usize,
    /// the raw line, as read in the file
    pub raw: String,
}

impl LogLine {
    pub fn datetime(&self) -> DateTime {
        DateTime { date: self.date, time: self.time }
    }
    /// whether the path looks like a resource (image, script, etc.)
    pub fn is_resource(&self) -> bool {
        let ext = match self.path.rfind('.') {
            Some(i) => &self.path[i + 1..],
            None => self.path.as_str(),
        };
        matches!(
            ext,
            "png" | "jpg" | "jpeg" | "gif" | "svg" | "ico" | "css" | "js" | "woff2" | "webp"
        )
    }
}

const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

fn parse_2digits(b: &[u8]) -> Option<u8> {
    if b.len() < 2 || !b[0].is_ascii_digit() || !b[1].is_ascii_digit() {
        return None;
    }
    Some((b[0] - b'0') * 10 + (b[1] - b'0'))
}

/// parse the date-time of a log line: `DD/Mon/YYYY:HH:MM:SS`
fn parse_datetime(b: &[u8]) -> Option<DateTime> {
    if b.len() < 20 {
        return None;
    }
    let day = parse_2digits(&b[0..2])?;
    if day == 0 || day > 31 || b[2] != b'/' {
        return None;
    }
    let mon_str = &b[3..6];
    let month = MONTHS.iter().position(|m| m.as_bytes() == mon_str)? as u8 + 1;
    if b[6] != b'/' {
        return None;
    }
    let ys = &b[7..11];
    if !ys.iter().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let year: u16 = std::str::from_utf8(ys).ok()?.parse().ok()?;
    if b[11] != b':' {
        return None;
    }
    let hour = parse_2digits(&b[12..14])?;
    if hour > 23 || b[14] != b':' {
        return None;
    }
    let minute = parse_2digits(&b[15..17])?;
    if minute > 59 || b[17] != b':' {
        return None;
    }
    let second = parse_2digits(&b[18..20])?;
    if second > 59 {
        return None;
    }
    Some(DateTime {
        date: Date { year, month, day },
        time: Time { hour, minute, second },
    })
}

fn find(b: &[u8], from: usize, c: u8) -> Option<usize> {
    b[from..].iter().position(|x| *x == c).map(|p| p + from)
}

/// parse a nginx "combined" log line
pub fn parse_line(raw: &str) -> Option<LogLine> {
    let b = raw.as_bytes();
    // remote address: up to the first space
    let sp = find(b, 0, b' ')?;
    let remote_addr = raw[..sp].to_string();
    // date between brackets
    let ob = find(b, sp, b'[')?;
    let dt = parse_datetime(&b[ob + 1..])?;
    let cb = find(b, ob + 1, b']')?;
    // request between quotes
    let q1 = find(b, cb + 1, b'"')?;
    let q2 = find(b, q1 + 1, b'"')?;
    let request = &raw[q1 + 1..q2];
    // " status bytes "
    let mut i = q2 + 1;
    if i >= b.len() || b[i] != b' ' {
        return None;
    }
    i += 1;
    let s_end = find(b, i, b' ')?;
    let status: u16 = raw[i..s_end].parse().ok()?;
    i = s_end + 1;
    let b_end = find(b, i, b' ')?;
    let bytes_sent: u64 = raw[i..b_end].parse().ok()?;
    i = b_end + 1;
    if i >= b.len() || b[i] != b'"' {
        return None;
    }
    let r_end = find(b, i + 1, b'"')?;
    let referer = raw[i + 1..r_end].to_string();
    // method and path
    let (method, path) = match request.find(' ') {
        Some(p) => {
            let m = &request[..p];
            let rest = &request[p + 1..];
            let path = match rest.find(' ') {
                Some(e) => &rest[..e],
                None => rest,
            };
            let path = match path.find('?') {
                Some(q) => &path[..q],
                None => path,
            };
            (Method::from_str(m), path.to_string())
        }
        None => (Method::None, request.to_string()),
    };
    Some(LogLine {
        remote_addr,
        date: dt.date,
        time: dt.time,
        method,
        path,
        status,
        bytes_sent,
        referer,
        date_idx: 0,
        raw: raw.to_string(),
    })
}
EOF
