    pub file_starts: Vec<Date>,
}

fn read_file_content(path: &Path) -> Result<Vec<u8>, RhitError> {
    let mut file = fs::File::open(path)?;
    let is_gz = path
        .extension()
        .map(|e| e == "gz")
        .unwrap_or(false);
    let mut content = Vec::new();
    if is_gz {
        let mut dec = flate2::read::GzDecoder::new(file);
        dec.read_to_end(&mut content)?;
    } else {
        file.read_to_end(&mut content)?;
    }
    Ok(content)
}

fn split_lines(content: &[u8]) -> Vec<String> {
    let mut lines: Vec<String> = content
        .split(|b| *b == b'\n')
        .map(|l| String::from_utf8_lossy(l).into_owned())
        .collect();
    if let Some(last) = lines.last() {
        if last.is_empty() {
            lines.pop();
        }
    }
    lines
}

/// check whether the file looks like a log file (one of the 3 first
/// lines must parse) and return the parsed lines if it is
fn read_log_file(path: &Path) -> Option<LogFile> {
    let content = match read_file_content(path) {
        Ok(c) => c,
        Err(_) => return None,
    };
    let raw_lines = split_lines(&content);
    let mut ok = false;
    for l in raw_lines.iter().take(3) {
        if parse_line(l).is_some() {
            ok = true;
            break;
        }
    }
    if !ok {
        return None;
    }
    let lines: Vec<LogLine> = raw_lines.iter().filter_map(|l| parse_line(l)).collect();
    let first = lines.first()?.datetime();
    Some(LogFile { path: path.to_path_buf(), lines, first })
}

fn is_log_file_name(path: &Path) -> bool {
    path.file_name()
        .map(|n| n.to_string_lossy().contains("access.log"))
        .unwrap_or(false)
}

fn collect_files(path: &Path, check_names: bool, files: &mut Vec<LogFile>) -> Result<(), RhitError> {
    if path.is_dir() {
        let mut entries: Vec<PathBuf> = fs::read_dir(path)?
            .filter_map(|e| e.ok())
            .map(|e| e.path())
            .collect();
        entries.sort();
        for entry in entries {
            if entry.is_dir() {
                collect_files(&entry, check_names, files)?;
            } else if !check_names || is_log_file_name(&entry) {
                if let Some(lf) = read_log_file(&entry) {
                    files.push(lf);
                }
            }
        }
    } else if let Some(lf) = read_log_file(path) {
        files.push(lf);
    }
    Ok(())
}

pub struct LoadOptions {
    pub check_names: bool,
    pub silent: bool,
}

fn write_progress(done: usize, total: usize) {
    let mut err = std::io::stderr();
    let mut w = Writer::new(&mut err, true);
    w.write_str(&format!("\x1b7\x1b[2K{:>4} / {} ", done, total));
    let eighths = if total == 0 {
        0
    } else {
        (320.0 * done as f64 / total as f64).round() as usize
    };
    let mut bar = String::new();
    let full = eighths / 8;
    let rem = eighths % 8;
    for _ in 0..full {
        bar.push('█');
    }
    let mut len = full;
    if rem > 0 {
        bar.push(crate::histo::EIGHTHS[rem]);
        len += 1;
    }
    while len < 40 {
        bar.push(' ');
        len += 1;
    }
    w.write_styled(&bar, Style::fg(11).with_bg(5));
    w.write_str("\x1b8");
    let _ = err.flush();
}

impl LogBase {
    /// load the log files found in the given paths
    pub fn load(paths: &[PathBuf], options: &LoadOptions) -> Result<LogBase, RhitError> {
        for p in paths {
            if !p.exists() {
                return Err(RhitError::PathNotFound(p.to_string_lossy().to_string()));
            }
        }
        // collect files (and parse them)
        let mut files: Vec<LogFile> = Vec::new();
        // paths given explicitly aren't name checked
        for p in paths {
            if p.is_dir() {
                collect_files(p, options.check_names, &mut files)?;
            } else if let Some(lf) = read_log_file(p) {
                files.push(lf);
            }
        }
        if files.is_empty() {
            return Err(RhitError::NoLogFileFound);
        }
        if !options.silent {
            let total = files.len();
            write_progress(0, total);
            for i in 0..total {
                write_progress(i + 1, total);
            }
            let mut err = std::io::stderr();
            let _ = err.write_all(b"\x1b7\x1b[2K\x1b8");
            let msg = if paths.len() == 1 {
                format!(
                    "I've read {} file{} in {:?}\n",
                    total,
                    if total > 1 { "s" } else { "" },
                    paths[0]
                )
            } else {
                format!(
                    "I've read {} file{} in {:?}\n",
                    total,
                    if total > 1 { "s" } else { "" },
                    paths
                )
            };
            let _ = err.write_all(msg.as_bytes());
            let _ = err.flush();
        }
        files.sort_by(|a, b| a.first.cmp(&b.first));
        let file_starts: Vec<Date> = files.iter().map(|f| f.first.date).collect();
        let mut dates: Vec<Date> = Vec::new();
        let mut lines: Vec<LogLine> = Vec::new();
        for f in files {
            for mut line in f.lines {
                match dates.last() {
                    Some(d) if *d == line.date => {}
                    _ => dates.push(line.date),
                }
                line.date_idx = dates.len() - 1;
                lines.push(line);
            }
        }
        Ok(LogBase { dates, lines, file_starts })
    }

    /// the year of the first line of the files, if they all agree
    pub fn implicit_year(&self) -> Option<u16> {
        let first = self.file_starts.first()?;
        if self.file_starts.iter().all(|d| d.year == first.year) {
            Some(first.year)
        } else {
            None
        }
    }
    /// the month of the first line of the files, if they all agree
    pub fn implicit_month(&self) -> Option<u8> {
        let first = self.file_starts.first()?;
        if self
            .file_starts
            .iter()
            .all(|d| d.year == first.year && d.month == first.month)
        {
            Some(first.month)
        } else {
            None
        }
    }
}
