fn parse_period(s: &str, imp: Implicit) -> Result<(DateTime, DateTime), DateTimeError> {
    let toks = tokens(s);
    let t0 = Time { hour: 0, minute: 0, second: 0 };
    let t1 = Time { hour: 23, minute: 59, second: 59 };
