            let dt = DateTime { date: Date { year, month, day }, time };
            Ok((dt, dt))
        }
    }
}

impl DateFilter {
    pub fn new(pattern: &str, imp: Implicit) -> Result<Self, DateTimeError> {
        let kind = if let Some(rest) = pattern.strip_prefix('!') {
            Kind::Not(parse_point(rest, imp)?)
        } else if let Some(rest) = pattern.strip_prefix('>') {
            Kind::After(parse_point(rest, imp)?)
        } else if let Some(rest) = pattern.strip_prefix('<') {
            Kind::Before(parse_point(rest, imp)?)
        } else if pattern.contains('-') {
            let mut parts = pattern.split('-');
            let a = parse_point(parts.next().unwrap_or(""), imp)?;
            let b = parse_point(parts.next().unwrap_or(""), imp)?;
            Kind::Range(a, b)
        } else {
            let (start, end) = parse_period(pattern, imp)?;
            Kind::Period { start, end }
        };
        Ok(DateFilter { kind })
    }

