    pub fn contains(&self, dt: DateTime) -> bool {
        match &self.kind {
            Kind::Period { start, end } => *start <= dt && dt <= *end,
            Kind::Not(p) => match p.time {
                Some(_) => dt != p.start(),
                None => dt.date != p.date,
            },
            Kind::After(p) => dt > p.end(),
            Kind::Before(p) => dt < p.start(),
            Kind::Range(a, b) => a.start() <= dt && dt <= b.end(),
