//! filtering on the time of the day

use crate::{
    errors::{TimeFilterError, TimeParseError},
    log::Time,
};

#[derive(Debug)]
enum Kind {
    After(Time),
    Before(Time),
    Range(Time, Time),
}

#[derive(Debug)]
pub struct TimeFilter {
    kind: Kind,
}

fn parse_u8(s: &str) -> Result<u8, TimeParseError> {
    s.parse().map_err(TimeParseError::IntExpected)
}

/// parse a time written as HH, HH:MM or HH:MM:S
fn parse_time(s: &str) -> Result<Time, TimeParseError> {
    let s = s.trim();
    let chars: Vec<char> = s.chars().collect();
    if chars.len() < 2 {
        return Err(TimeParseError::UnexpectedEnd);
    }
    let sub = |a: usize, b: usize| -> String { chars[a..b].iter().collect() };
    let hour = parse_u8(&sub(0, 2))?;
    if hour > 23 {
        return Err(TimeParseError::InvalidHour(hour));
    }
    let mut minute = 0;
    let mut second = 0;
    if chars.len() >= 5 && chars[2] == ':' {
        minute = parse_u8(&sub(3, 5))?;
        if minute > 59 {
            return Err(TimeParseError::InvalidMinute(minute));
        }
        if chars.len() >= 7 && chars[5] == ':' {
            second = parse_u8(&sub(6, 7))?;
        }
    }
    Ok(Time { hour, minute, second })
}

impl TimeFilter {
    pub fn new(pattern: &str) -> Result<Self, TimeFilterError> {
        let kind = if let Some(rest) = pattern.strip_prefix('>') {
            Kind::After(parse_time(rest).map_err(TimeFilterError::TimeParse)?)
        } else if let Some(rest) = pattern.strip_prefix('<') {
            Kind::Before(parse_time(rest).map_err(TimeFilterError::TimeParse)?)
        } else {
            let parts: Vec<&str> = pattern.split('-').collect();
            if parts.len() != 2 || parts[0].is_empty() || parts[1].is_empty() {
                return Err(TimeFilterError::InvalidFormat);
            }
            let a = parse_time(parts[0]).map_err(TimeFilterError::TimeParse)?;
            let b = parse_time(parts[1]).map_err(TimeFilterError::TimeParse)?;
            Kind::Range(a, b)
        };
        Ok(TimeFilter { kind })
    }
    pub fn contains(&self, t: Time) -> bool {
        match &self.kind {
            Kind::After(a) => t > *a,
            Kind::Before(b) => t < *b,
            Kind::Range(a, b) => {
                if a <= b {
                    *a <= t && t <= *b
                } else {
                    t >= *a || t <= *b
                }
            }
        }
    }
}
