//! filtering on the HTTP status

use crate::errors::StatusFilterError;

#[derive(Debug)]
enum Term {
    Class(u16), // 2 for 2xx, etc.
    Range(u16, u16),
    Value(u16),
}

impl Term {
    fn matches(&self, status: u16) -> bool {
        match self {
            Term::Class(c) => status / 100 == *c,
            Term::Range(a, b) => *a <= status && status <= *b,
            Term::Value(v) => status == *v,
        }
    }
}

#[derive(Debug)]
pub struct StatusFilter {
    positives: Vec<Term>,
    negatives: Vec<Term>,
}

fn parse_u16(s: &str) -> Result<u16, StatusFilterError> {
    s.parse().map_err(StatusFilterError::ParseInt)
}

fn parse_term(s: &str) -> Result<Term, StatusFilterError> {
    match s {
        "2xx" => return Ok(Term::Class(2)),
        "3xx" => return Ok(Term::Class(3)),
        "4xx" => return Ok(Term::Class(4)),
        "5xx" => return Ok(Term::Class(5)),
        _ => {}
    }
    if let Some(idx) = s.find('-') {
        let a = parse_u16(&s[..idx])?;
        let b = parse_u16(&s[idx + 1..])?;
        return Ok(Term::Range(a, b));
    }
    Ok(Term::Value(parse_u16(s)?))
}

impl StatusFilter {
    pub fn new(pattern: &str) -> Result<Self, StatusFilterError> {
        let mut positives = Vec::new();
        let mut negatives = Vec::new();
        for part in pattern.split(',') {
            let part = part.trim();
            if let Some(rest) = part.strip_prefix('!') {
                negatives.push(parse_term(rest)?);
            } else {
                positives.push(parse_term(part)?);
            }
        }
        Ok(StatusFilter { positives, negatives })
    }
    pub fn contains(&self, status: u16) -> bool {
        if self.negatives.iter().any(|t| t.matches(status)) {
            return false;
        }
        self.positives.is_empty() || self.positives.iter().any(|t| t.matches(status))
    }
}
