fn build(items: Vec<Item>) -> Result<Option<Node>, StrFilterError> {
    let mut iter = items.into_iter().peekable();
    fn operand(
        iter: &mut std::iter::Peekable<std::vec::IntoIter<Item>>,
    ) -> Result<Option<Node>, StrFilterError> {
        let mut nots = 0;
        while let Some(Item::Not) = iter.peek() {
            iter.next();
            nots += 1;
        }
        let mut node = match iter.peek() {
            Some(Item::Atom(_)) => match iter.next() {
                Some(Item::Atom(s)) => Some(Node::Atom(regex(&s)?)),
                _ => unreachable!(),
            },
            Some(Item::Sub(_)) => match iter.next() {
                Some(Item::Sub(n)) => Some(n),
                _ => unreachable!(),
            },
            _ => None,
        };
        for _ in 0..nots {
            node = Some(Node::Not(node.map(Box::new)));
        }
        Ok(node)
