        let op = *op;
        iter.next();
        let right = operand(&mut iter)?;
        node = match node {
            Some(left) => Some(Node::Bin(op, Box::new(left), right.map(Box::new))),
            None => right, // can't happen: operators need a left operand
        };
    }
    // remaining items (atoms after a complete operand) are ignored
    Ok(node)
