    fn accepts_binary(&self) -> bool {
        matches!(self.items.last(), Some(Item::Atom(_)) | Some(Item::Sub(_)))
    }
}

fn parse_expression(pattern: &str) -> Result<Option<Node>, StrFilterError> {
    let chars: Vec<char> = pattern.chars().collect();
    let mut levels: Vec<Level> = vec![Level { items: Vec::new() }];
    let mut in_atom = false; // whether the last item is an atom being written
    for (i, &c) in chars.iter().enumerate() {
        let prev = if i > 0 { Some(chars[i - 1]) } else { None };
