//! the fields on which tables are displayed

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Field {
    Date,
    Time,
    Method,
    Status,
    Ip,
    Referer,
    Path,
}

pub const ALL_FIELDS: [Field; 7] = [
    Field::Date,
    Field::Time,
    Field::Method,
    Field::Status,
    Field::Ip,
    Field::Referer,
    Field::Path,
];

pub const DEFAULT_FIELDS: [Field; 4] = [Field::Date, Field::Status, Field::Referer, Field::Path];

#[derive(Clone, Debug)]
pub struct Fields(pub Vec<Field>);

impl Default for Fields {
    fn default() -> Self {
        Fields(DEFAULT_FIELDS.to_vec())
    }
}

enum Token {
    Field(Field),
    All,
}

fn token(s: &str) -> Result<Token, String> {
    let c = s.chars().next().unwrap();
    match c.to_lowercase().next().unwrap_or(c) {
        'd' => Ok(Token::Field(Field::Date)),
        't' => Ok(Token::Field(Field::Time)),
        'm' => Ok(Token::Field(Field::Method)),
        's' => Ok(Token::Field(Field::Status)),
        'i' => Ok(Token::Field(Field::Ip)),
        'r' => Ok(Token::Field(Field::Referer)),
        'p' => Ok(Token::Field(Field::Path)),
        'a' => Ok(Token::All),
        _ => Err(format!("unrecognized field start '{}'", c)),
    }
}

impl std::str::FromStr for Fields {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, String> {
        let mut fields: Vec<Field> = if s.starts_with('+') || s.starts_with('-') {
            DEFAULT_FIELDS.to_vec()
        } else {
            Vec::new()
        };
        let mut remove = false;
        let mut tok = String::new();
        let apply = |fields: &mut Vec<Field>, remove: bool, tok: &str| -> Result<(), String> {
            if tok.is_empty() {
                return Ok(());
            }
            match token(tok)? {
                Token::All => {
                    if remove {
                        fields.clear();
                    } else {
                        *fields = ALL_FIELDS.to_vec();
                    }
                }
                Token::Field(f) => {
                    fields.retain(|x| *x != f);
                    if !remove {
                        fields.push(f);
                    }
                }
            }
            Ok(())
        };
        for c in s.chars() {
            match c {
                ',' | '+' => {
                    apply(&mut fields, remove, &tok)?;
                    tok.clear();
                    remove = false;
                }
                '-' => {
                    apply(&mut fields, remove, &tok)?;
                    tok.clear();
                    remove = true;
                }
                _ => tok.push(c),
            }
        }
        apply(&mut fields, remove, &tok)?;
        Ok(Fields(fields))
    }
}
