//! histogram characters

/// partial block characters, indexed by eighths (0 is empty)
pub const EIGHTHS: [char; 8] = [' ', '▏', '▎', '▍', '▌', '▋', '▊', '▉'];

/// bar of the given max width (in chars), with eighth precision
pub fn bar(value: u64, max: u64, width: usize) -> String {
    let mut s = String::new();
    if max == 0 || value == 0 {
        return s;
    }
    let eighths = (value as f64 * (width * 8) as f64 / max as f64).round() as usize;
    let full = eighths / 8;
    let rem = eighths % 8;
    for _ in 0..full {
        s.push('█');
    }
    if rem > 0 {
        s.push(EIGHTHS[rem]);
    }
    s
}

const SPARK: [char; 8] = [' ', '▁', '▂', '▃', '▄', '▅', '▆', '▇'];

/// one char per value, relative to the max
pub fn sparkline(values: &[u64]) -> String {
    let max = values.iter().copied().max().unwrap_or(0);
    values
        .iter()
        .map(|&v| {
            if max == 0 || v == 0 {
                ' '
            } else {
                let level = (7.0 * v as f64 / max as f64).round() as usize;
                SPARK[level.min(7)]
            }
        })
        .collect()
}
