//! trend computation: comparison of the last two days with the previous ones

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Trend {
    /// total number of hits (not just in the window)
    pub hits: u64,
    pub value: f64,
    /// difference of shares, used to break ties
    pub diff: f64,
}

impl Trend {
    pub fn compute(
        hits: u64,
        entry_values: &[u64],  // values over the window dates
        totals: &[u64],        // totals over the same window dates
    ) -> Trend {
        let n = entry_values.len();
        if n < 2 {
            return Trend { hits, value: 0.0, diff: 0.0 };
        }
        let tail_start = n - 2;
        let ref_count: u64 = entry_values[..tail_start].iter().sum();
        let tail_count: u64 = entry_values[tail_start..].iter().sum();
        let ref_total: u64 = totals[..tail_start].iter().sum();
        let tail_total: u64 = totals[tail_start..].iter().sum();
        let rs = if ref_total > 0 { ref_count as f64 / ref_total as f64 } else { 0.0 };
        let ts = if tail_total > 0 { tail_count as f64 / tail_total as f64 } else { 0.0 };
        let diff = ts - rs;
        let value = if ts + rs > 0.0 { diff / (ts + rs) } else { 0.0 };
        Trend { hits, value, diff }
    }
    /// number of arrows: positive for up, negative for down
    pub fn arrows(&self) -> i32 {
        if self.hits < 10 {
            return 0;
        }
        let v = self.value;
        let a = v.abs();
        let n = if a > 0.9 {
            3
        } else if a > 0.5 {
            2
        } else if a > 0.2 {
            1
        } else {
            0
        };
        if v < 0.0 { -n } else { n }
    }
    pub fn sort_key(&self) -> (f64, f64) {
        (self.value, self.diff)
    }
}
