cat > /workspace/src/tables.rs <<'EOF'
//! computation and printing of the summary tables

use crate::{
    base::LogBase,
    fields::Field,
    filters::DateFilter,
    fmt::{fit_4, percent1, with_thousands},
    histo,
    log::{LogLine, Method},
    md::{Align, Compound, Style, Table, Writer},
    trend::Trend,
};
use std::collections::HashMap;
use std::hash::Hash;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Key {
    Hits,
    Bytes,
}

impl std::str::FromStr for Key {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, String> {
        match s {
            "h" | "hits" => Ok(Key::Hits),
            "b" | "bytes" => Ok(Key::Bytes),
            _ => Err(format!("unrecognized key {:?}", s)),
        }
    }
}

pub const KEY_STYLE: Style = Style::fg(204);
pub const BOLD: Style = Style::fg_bold(11);
pub const CODE: Style = Style::fg(11).with_code();
pub const TITLE: Style = Style::fg(178);
pub const DOWN: Style = Style::fg(9);
pub const UP: Style = Style::fg(10);

pub const WINDOW: usize = 20;

pub struct Printer<'w> {
    pub w: Writer<'w>,
    pub width: usize,
    pub key: Key,
    pub length: usize,
    pub all_paths: bool,
    pub changes: bool,
}

fn b(s: &str) -> Compound {
    Compound::new(s, BOLD)
}
fn p(s: &str) -> Compound {
    Compound::plain(s)
}
fn t(s: &str) -> Compound {
    Compound::new(s, TITLE)
}

/// the counts of an entry (a path, an IP, etc.)
#[derive(Clone, Debug, Default)]
struct Counts {
    hits: u64,
    bytes: u64,
    /// (hits, bytes) per date index
    per_date: Vec<(u64, u64)>,
}

impl Counts {
    fn key(&self, key: Key) -> u64 {
        match key {
            Key::Hits => self.hits,
            Key::Bytes => self.bytes,
        }
    }
    fn date_key(&self, i: usize, key: Key) -> u64 {
        match self.per_date.get(i) {
            Some((h, b)) => match key {
                Key::Hits => *h,
                Key::Bytes => *b,
            },
            None => 0,
        }
    }
    fn add(&mut self, line: &LogLine) {
        self.hits += 1;
        self.bytes += line.bytes_sent;
        if let Some(d) = self.per_date.get_mut(line.date_idx) {
            d.0 += 1;
            d.1 += line.bytes_sent;
        }
    }
}

struct Entry<K> {
    key: K,
    counts: Counts,
}

/// the filtered data on which tables are computed
pub struct Data<'b> {
    pub base: &'b LogBase,
    pub lines: Vec<&'b LogLine>,
    /// number of relevant dates (max date index + 1)
    pub n_dates: usize,
    /// totals (hits, bytes) per date, on the unfiltered base
    pub totals: Vec<(u64, u64)>,
    pub date_filter: Option<&'b DateFilter>,
}

impl<'b> Data<'b> {
    pub fn new(base: &'b LogBase, lines: Vec<&'b LogLine>, date_filter: Option<&'b DateFilter>) -> Self {
        let n_dates = lines.iter().map(|l| l.date_idx + 1).max().unwrap_or(0);
        let mut totals = vec![(0u64, 0u64); base.dates.len()];
        for l in &base.lines {
            if let Some(t) = totals.get_mut(l.date_idx) {
                t.0 += 1;
                t.1 += l.bytes_sent;
            }
        }
        Data { base, lines, n_dates, totals, date_filter }
    }
    pub fn trend_mode(&self) -> bool {
        self.n_dates >= 4
    }
    fn window(&self) -> std::ops::Range<usize> {
        self.n_dates.saturating_sub(WINDOW)..self.n_dates
    }
    fn total_hits(&self) -> u64 {
        self.lines.len() as u64
    }
    fn collect<K: Hash + Eq + Clone, F: Fn(&LogLine) -> Option<K>>(&self, f: F) -> Vec<Entry<K>> {
        let mut map: HashMap<K, usize> = HashMap::new();
        let mut entries: Vec<Entry<K>> = Vec::new();
        for line in &self.lines {
            if let Some(k) = f(line) {
                let idx = match map.get(&k) {
                    Some(i) => *i,
                    None => {
                        map.insert(k.clone(), entries.len());
                        entries.push(Entry {
                            key: k,
                            counts: Counts {
                                hits: 0,
                                bytes: 0,
                                per_date: vec![(0, 0); self.n_dates],
                            },
                        });
                        entries.len() - 1
                    }
                };
                entries[idx].counts.add(line);
            }
        }
        entries
    }
    fn trend(&self, counts: &Counts, key: Key) -> Trend {
        let window = self.window();
        let values: Vec<u64> = window.clone().map(|i| counts.date_key(i, key)).collect();
        let totals: Vec<u64> = window
            .map(|i| match key {
                Key::Hits => self.totals[i].0,
                Key::Bytes => self.totals[i].1,
            })
            .collect();
        Trend::compute(counts.hits, &values, &totals)
    }
    fn sparkline(&self, counts: &Counts, key: Key) -> String {
        let values: Vec<u64> = self.window().map(|i| counts.date_key(i, key)).collect();
        histo::sparkline(&values)
    }
}

fn trend_cell(arrows: i32) -> Vec<Compound> {
    let (ch, style) = if arrows < 0 { ("➘", DOWN) } else { ("➚", UP) };
    let mut cell = Vec::new();
    for i in 0..arrows.abs() {
        if i > 0 {
            cell.push(p(" "));
        }
        cell.push(Compound::new(ch, style));
    }
    cell
}

fn rows_count(field: Field, length: usize) -> Option<usize> {
    match field {
        Field::Ip => Some(match length {
            0 => 3,
            1 => 5,
            l => 10 * l,
        }),
        Field::Referer => Some(match length {
            0 => 5,
            1 => 10,
            l => 20 * l,
        }),
        Field::Path => Some(match length {
            0 => 10,
            1 => 50,
            l => 50 * l,
        }),
        _ => None,
    }
}

impl<'w> Printer<'w> {
    fn fmt_key(&self, v: u64) -> String {
        match self.key {
            Key::Hits => with_thousands(v),
            Key::Bytes => fit_4(v),
        }
    }
    fn hits_cell(&self, hits: u64) -> Vec<Compound> {
        let s = with_thousands(hits);
        vec![if self.key == Key::Hits { Compound::new(s, KEY_STYLE) } else { p(&s) }]
    }
    fn bytes_cell(&self, bytes: u64) -> Vec<Compound> {
        let s = fit_4(bytes);
        vec![if self.key == Key::Bytes { Compound::new(s, KEY_STYLE) } else { p(&s) }]
    }
    fn title(&mut self, compounds: &[Compound]) {
        self.w.write_text(compounds, self.width);
    }
    fn table(&mut self, table: &Table) {
        table.write(&mut self.w, self.width);
    }

    pub fn print_summary(&mut self, base: &LogBase) {
        let hits = with_thousands(base.lines.len() as u64);
        let bytes = fit_4(base.lines.iter().map(|l| l.bytes_sent).sum());
        let (first, last) = match (base.dates.first(), base.dates.last()) {
            (Some(f), Some(l)) => (f.to_string(), l.to_string()),
            _ => (String::new(), String::new()),
        };
        let mut cs = Vec::new();
        match self.key {
            Key::Hits => {
                cs.push(Compound::new(hits, KEY_STYLE));
                cs.push(p(&format!(" hits and {} from ", bytes)));
            }
            Key::Bytes => {
                cs.push(p(&format!("{} hits and ", hits)));
                cs.push(Compound::new(bytes, KEY_STYLE));
                cs.push(p(" from "));
            }
        }
        cs.push(b(&first));
        cs.push(p(" to "));
        cs.push(b(&last));
        self.w.write_text(&cs, self.width);
    }

    pub fn print_filter_result(&mut self, hits: u64, bytes: u64) {
        let mut cs = vec![p(" "), b("==>"), p(" hits: ")];
        match self.key {
            Key::Hits => {
                cs.push(Compound::new(with_thousands(hits), KEY_STYLE));
                cs.push(p(&format!(", bytes sent: {}", fit_4(bytes))));
            }
            Key::Bytes => {
                cs.push(p(&format!("{}, bytes sent: ", with_thousands(hits))));
                cs.push(Compound::new(fit_4(bytes), KEY_STYLE));
            }
        }
        self.w.write_text(&cs, self.width);
    }

    pub fn print_filtering(&mut self, field_name: &str, pattern: &str, removed: usize, total: usize) {
        let pct = if total > 0 { 100.0 * removed as f64 / total as f64 } else { 0.0 };
        let cs = vec![
            p(&format!("Filtering by {} on pattern ", field_name)),
            Compound::new(pattern, CODE),
            p(" removed "),
            b(&format!("{:.2}%", pct)),
            p(" of total lines"),
        ];
        self.w.write_text(&cs, self.width);
    }

    pub fn print_field(&mut self, data: &Data, field: Field) {
        match field {
            Field::Date => self.print_dates(data),
            Field::Time => self.print_times(data),
            Field::Method => self.print_methods(data),
            Field::Status => self.print_statuses(data),
            Field::Ip => self.print_ips(data),
            Field::Referer => self.print_referers(data),
            Field::Path => self.print_paths(data),
        }
    }

    fn histo_header(&self, max: u64) -> Vec<Compound> {
        vec![b(&format!("0{:>19}", self.fmt_key(max)))]
    }

    fn print_dates(&mut self, data: &Data) {
        let mut rows: Vec<(String, u64, u64)> = Vec::new();
        let mut counts = vec![(0u64, 0u64); data.n_dates];
        for l in &data.lines {
            if let Some(c) = counts.get_mut(l.date_idx) {
                c.0 += 1;
                c.1 += l.bytes_sent;
            }
        }
        for (i, date) in data.base.dates.iter().enumerate().take(data.n_dates) {
            if let Some(df) = data.date_filter {
                if !df.contains_date(*date) {
                    continue;
                }
            }
            rows.push((date.to_string(), counts[i].0, counts[i].1));
        }
        let max = rows
            .iter()
            .map(|r| match self.key {
                Key::Hits => r.1,
                Key::Bytes => r.2,
            })
            .max()
            .unwrap_or(0);
        let mut table = Table::new(vec![Align::Center, Align::Right, Align::Right, Align::Left]);
        table.push_row(vec![vec![b("date")], vec![b("hits")], vec![b("bytes")], self.histo_header(max)]);
        for (date, hits, bytes) in rows {
            let v = match self.key {
                Key::Hits => hits,
                Key::Bytes => bytes,
            };
            table.push_row(vec![
                vec![p(&date)],
                self.hits_cell(hits),
                self.bytes_cell(bytes),
                vec![Compound::new(histo::bar(v, max, 20), KEY_STYLE)],
            ]);
        }
        self.table(&table);
    }

    fn print_times(&mut self, data: &Data) {
        let mut counts = vec![(0u64, 0u64); 24];
        for l in &data.lines {
            let c = &mut counts[l.time.hour as usize];
            c.0 += 1;
            c.1 += l.bytes_sent;
        }
        let max = counts
            .iter()
            .map(|c| match self.key {
                Key::Hits => c.0,
                Key::Bytes => c.1,
            })
            .max()
            .unwrap_or(0);
        let mut table = Table::new(vec![Align::Left, Align::Center, Align::Right, Align::Left]);
        table.push_row(vec![vec![b("hour")], vec![b("hits")], vec![b("bytes")], self.histo_header(max)]);
        for (h, c) in counts.iter().enumerate() {
            let v = match self.key {
                Key::Hits => c.0,
                Key::Bytes => c.1,
            };
            table.push_row(vec![
                vec![p(&h.to_string())],
                self.hits_cell(c.0),
                self.bytes_cell(c.1),
                vec![Compound::new(histo::bar(v, max, 20), KEY_STYLE)],
            ]);
        }
        self.table(&table);
    }

    /// print a table of entries, either in simple mode or in trend mode
    fn print_entries_table<K>(
        &mut self,
        data: &Data,
        entries: &[Entry<K>],
        header: &str,
        with_idx: bool,
        with_percent: bool,
        key_align: Align,
        key_fmt: &dyn Fn(&K) -> String,
    ) {
        let total = data.total_hits();
        let trend_mode = data.trend_mode();
        let mut aligns = Vec::new();
        let mut hrow: Vec<Vec<Compound>> = Vec::new();
        if with_idx {
            aligns.push(Align::Right);
            hrow.push(vec![b("#")]);
        }
        aligns.push(key_align);
        hrow.push(vec![b(header)]);
        aligns.push(Align::Right);
        hrow.push(vec![b("hits")]);
        if with_percent {
            aligns.push(Align::Right);
            hrow.push(vec![b("%")]);
        }
        aligns.push(Align::Right);
        hrow.push(vec![b("bytes")]);
        if trend_mode {
            aligns.push(Align::Left);
            hrow.push(vec![b("days")]);
            aligns.push(Align::Center);
            hrow.push(vec![b("trend")]);
        }
        let mut table = Table::new(aligns);
        table.push_row(hrow);
        for (i, e) in entries.iter().enumerate() {
            let mut row: Vec<Vec<Compound>> = Vec::new();
            if with_idx {
                row.push(vec![p(&format!("{:>3}", i + 1))]);
            }
            row.push(vec![p(&key_fmt(&e.key))]);
            row.push(self.hits_cell(e.counts.hits));
            if with_percent {
                row.push(vec![p(&percent1(e.counts.hits, total))]);
            }
            row.push(self.bytes_cell(e.counts.bytes));
            if trend_mode {
                row.push(vec![Compound::new(data.sparkline(&e.counts, self.key), KEY_STYLE)]);
                let trend = data.trend(&e.counts, self.key);
                row.push(trend_cell(trend.arrows()));
            }
            table.push_row(row);
        }
        self.table(&table);
    }

    fn sort_entries<K>(&self, entries: &mut Vec<Entry<K>>) {
        let key = self.key;
        entries.sort_by(|a, b| b.counts.key(key).cmp(&a.counts.key(key)));
    }

    fn print_methods(&mut self, data: &Data) {
        let mut entries = data.collect(|l| Some(l.method));
        self.sort_entries(&mut entries);
        if data.trend_mode() {
            self.title(&[t("methods")]);
            self.print_entries_table(data, &entries, "method", false, true, Align::Center, &|m: &Method| {
                m.as_str().to_string()
            });
        } else {
            self.title(&[t(&entries.len().to_string()), t(" "), t("methods"), t(". "), t("")]);
            self.print_entries_table(data, &entries, "method", true, true, Align::Left, &|m: &Method| {
                m.as_str().to_string()
            });
        }
    }

    fn print_statuses(&mut self, data: &Data) {
        if self.length == 0 {
            // summary by class
            let total = data.total_hits();
            let mut classes = [0u64; 4];
            for l in &data.lines {
                let c = match l.status {
                    200..=299 => 0,
                    300..=399 => 1,
                    400..=499 => 2,
                    _ => 3,
                };
                classes[c] += 1;
            }
            self.title(&[t("HTTP status codes:")]);
            let mut table = Table::new(vec![Align::Center; 4]);
            table.push_row(vec![vec![b("2xx")], vec![b("3xx")], vec![b("4xx")], vec![b("5xx")]]);
            table.push_row(classes.iter().map(|c| vec![p(&percent1(*c, total))]).collect());
            self.table(&table);
            return;
        }
        let mut entries = data.collect(|l| Some(l.status));
        self.sort_entries(&mut entries);
        if data.trend_mode() {
            self.title(&[t("HTTP status codes")]);
            self.print_entries_table(data, &entries, "status", false, true, Align::Center, &|s: &u16| {
                s.to_string()
            });
        } else {
            self.title(&[t(&entries.len().to_string()), t(" "), t("HTTP status codes"), t(". "), t("")]);
            self.print_entries_table(data, &entries, "status", true, true, Align::Left, &|s: &u16| {
                s.to_string()
            });
        }
    }

    /// print the tables of a string keyed field (ip, referer, path)
    fn print_str_field(&mut self, data: &Data, field: Field, entries: Vec<Entry<String>>, name: &str, header: &str) {
        let mut entries = entries;
        self.sort_entries(&mut entries);
        let n = entries.len();
        let rows = rows_count(field, self.length).unwrap_or(n);
        let truncated = n > rows;
        let shown = &entries[..n.min(rows)];
        if data.trend_mode() {
            let more = if truncated { format!(". {} most frequent:", rows) } else { String::new() };
            self.title(&[t(&format!("{} {}{}", n, name, more))]);
            self.print_entries_table(data, shown, header, true, false, Align::Left, &|s: &String| s.clone());
            if self.changes {
                let mut with_trends: Vec<(Trend, &Entry<String>)> = entries
                    .iter()
                    .map(|e| (data.trend(&e.counts, self.key), e))
                    .filter(|(t, _)| t.hits >= 10)
                    .collect();
                with_trends.sort_by(|a, b| {
                    let ka = a.0.sort_key();
                    let kb = b.0.sort_key();
                    ka.partial_cmp(&kb).unwrap_or(std::cmp::Ordering::Equal)
                });
                let less: Vec<&Entry<String>> = with_trends.iter().map(|(_, e)| *e).take(rows).collect();
                let more_entries: Vec<&Entry<String>> = with_trends.iter().rev().map(|(_, e)| *e).take(rows).collect();
                self.title(&[t(&format!("More popular {}", name))]);
                self.print_ref_table(data, &more_entries, header);
                self.title(&[t(&format!("Less popular {}", name))]);
                self.print_ref_table(data, &less, header);
            }
        } else {
            let more = if truncated { format!("{} most frequent:", rows) } else { String::new() };
            self.title(&[t(&n.to_string()), t(" "), t(name), t(". "), t(&more)]);
            self.print_entries_table(data, shown, header, true, true, Align::Left, &|s: &String| s.clone());
        }
    }

    fn print_ref_table(&mut self, data: &Data, entries: &[&Entry<String>], header: &str) {
        let owned: Vec<Entry<String>> = entries
            .iter()
            .map(|e| Entry { key: e.key.clone(), counts: e.counts.clone() })
            .collect();
        self.print_entries_table(data, &owned, header, true, false, Align::Left, &|s: &String| s.clone());
    }

    fn print_ips(&mut self, data: &Data) {
        let entries = data.collect(|l| Some(l.remote_addr.clone()));
        self.print_str_field(data, Field::Ip, entries, "remote IP addresses", "IP address");
    }

    fn print_referers(&mut self, data: &Data) {
        let entries = data.collect(|l| if l.referer == "-" { None } else { Some(l.referer.clone()) });
        self.print_str_field(data, Field::Referer, entries, "referrers", "referrer");
    }

    fn print_paths(&mut self, data: &Data) {
        let all = self.all_paths;
        let entries = data.collect(|l| if !all && l.is_resource() { None } else { Some(l.path.clone()) });
