mod base;
mod errors;
mod fields;
mod filters;
mod fmt;
mod help;
mod histo;
mod log;
mod md;
mod output;
mod tables;
mod term;
mod trend;

use crate::{
    base::{LoadOptions, LogBase},
    errors::RhitError,
    fields::Fields,
    filters::{date_filter::Implicit, DateFilter, MethodFilter, StatusFilter, StrFilter, TimeFilter},
    log::LogLine,
    md::Writer,
    output::Output,
    tables::{Data, Key, Printer},
};
use clap::{Arg, ArgAction, Command};
use std::{io::Write, path::PathBuf, str::FromStr};

/// print a message mimicking a Rust panic, then exit with the panic exit code
pub fn panic_like(location: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    let tid = unsafe { gettid() };
    eprintln!("\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", tid, location, msg);
    std::process::exit(101);
}

extern "C" {
    fn gettid() -> i32;
}

fn parse_key(s: &str) -> Result<Key, String> {
    Key::from_str(s)
}
fn parse_output(s: &str) -> Result<Output, String> {
    Output::from_str(s)
}
fn parse_fields(s: &str) -> Result<Fields, String> {
    Fields::from_str(s)
}

fn command() -> Command {
    Command::new("rhit")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help").long("help").action(ArgAction::SetTrue).help("Print help information"))
        .arg(Arg::new("version").long("version").action(ArgAction::SetTrue).help("Print the version"))
        .arg(
            Arg::new("color")
                .long("color")
                .value_name("color")
                .value_parser(["auto", "yes", "no"])
                .default_value("auto"),
        )
        .arg(
            Arg::new("key")
                .short('k')
                .long("key")
                .value_name("KEY")
                .value_parser(parse_key)
                .default_value("hits"),
        )
        .arg(
            Arg::new("length")
                .short('l')
                .long("length")
                .value_name("LENGTH")
                .value_parser(clap::value_parser!(usize))
                .default_value("1"),
        )
        .arg(Arg::new("fields").short('f').long("fields").value_name("FIELDS").value_parser(parse_fields))
        .arg(Arg::new("changes").short('c').long("changes").action(ArgAction::SetTrue))
        .arg(Arg::new("date").short('d').long("date").value_name("DATE"))
        .arg(Arg::new("ip").short('i').long("ip").value_name("IP"))
        .arg(Arg::new("method").short('m').long("method").value_name("METHOD"))
        .arg(Arg::new("path").short('p').long("path").value_name("PATH"))
        .arg(Arg::new("referer").short('r').long("referer").value_name("REFERER"))
        .arg(Arg::new("status").short('s').long("status").value_name("STATUS"))
        .arg(Arg::new("time").short('t').long("time").value_name("TIME"))
        .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
        .arg(Arg::new("no-name-check").long("no-name-check").action(ArgAction::SetTrue))
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("OUTPUT")
                .value_parser(parse_output)
                .default_value("tables"),
        )
        .arg(Arg::new("silent-load").long("silent-load").action(ArgAction::SetTrue))
        .arg(
            Arg::new("files")
                .value_name("FILES")
                .num_args(0..)
                .action(ArgAction::Append)
                .value_parser(clap::value_parser!(PathBuf)),
        )
}

fn main() {
    let matches = match command().try_get_matches() {
        Ok(m) => m,
        Err(e) => e.exit(),
    };
    if matches.get_flag("help") {
        let mut out = std::io::stdout();
        help::print_help(&mut out, term::terminal_width());
        let _ = out.flush();
        return;
    }
    if matches.get_flag("version") {
        println!("rhit 2.0.4");
        return;
    }
    if let Err(e) = run(&matches) {
        let _ = std::io::stdout().flush();
        eprintln!("Error: {:?}", e);
        std::process::exit(1);
    }
}

fn run(matches: &clap::ArgMatches) -> Result<(), RhitError> {
    let mut paths: Vec<PathBuf> = matches
        .get_many::<PathBuf>("files")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let default_location = paths.is_empty();
    if default_location {
