//! filtering strings (paths, referers, remote addresses) with regular
//! expressions combined in boolean expressions

use crate::errors::StrFilterError;
use regex::Regex;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Op {
    And,
    Or,
    Not,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Child {
    None,
    Node(usize),
    Atom(usize),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Token {
    Nothing,
    Atom,
    Operator,
    OpeningPar,
    ClosingPar,
}

#[derive(Debug, Clone)]
struct Node {
    operator: Option<Op>,
    parent: Option<usize>,
    left: Child,
    right: Child,
    unary: bool,
}

impl Node {
    fn new(parent: Option<usize>) -> Self {
        Node { operator: None, parent, left: Child::None, right: Child::None, unary: false }
    }
}

/// A binary expression tree, built incrementally
#[derive(Debug)]
struct BeTree {
    atoms: Vec<String>,
    nodes: Vec<Node>,
    head: usize,
    tail: usize,
    last_pushed: Token,
    op_count: usize,
    openness: usize,
}

impl BeTree {
    fn new() -> Self {
        BeTree {
            atoms: Vec::new(),
            nodes: vec![Node::new(None)],
            head: 0,
            tail: 0,
            last_pushed: Token::Nothing,
            op_count: 0,
            openness: 0,
        }
    }
    fn accepts_operand(&self) -> bool {
        matches!(self.last_pushed, Token::Nothing | Token::Operator | Token::OpeningPar)
    }
    fn accepts_binary(&self) -> bool {
        matches!(self.last_pushed, Token::Atom | Token::ClosingPar)
    }
    fn add_child(&mut self, child: Child) {
        let tail = &mut self.nodes[self.tail];
        if tail.left == Child::None {
            tail.left = child;
        } else {
            tail.right = child;
        }
    }
    fn push_atom_char(&mut self, c: char) {
        if self.last_pushed == Token::Atom {
            if let Some(a) = self.atoms.last_mut() {
                a.push(c);
                return;
            }
        }
        self.atoms.push(c.to_string());
        let idx = self.atoms.len() - 1;
        self.add_child(Child::Atom(idx));
        self.last_pushed = Token::Atom;
    }
    fn push_unary(&mut self, op: Op) {
        self.op_count += 1;
        let node = Node {
            operator: Some(op),
            parent: Some(self.tail),
            left: Child::None,
            right: Child::None,
            unary: true,
        };
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.add_child(Child::Node(idx));
        self.tail = idx;
        self.last_pushed = Token::Operator;
    }
    fn push_binary(&mut self, op: Op) {
        self.op_count += 1;
        let tail = self.tail;
        if self.nodes[tail].operator.is_none() {
            self.nodes[tail].operator = Some(op);
        } else {
            let parent = self.nodes[tail].parent;
            let node = Node { operator: Some(op), parent, left: Child::Node(tail), right: Child::None, unary: false };
            self.nodes.push(node);
            let idx = self.nodes.len() - 1;
            match parent {
                Some(p) => {
                    let pn = &mut self.nodes[p];
                    if pn.left == Child::Node(tail) {
                        pn.left = Child::Node(idx);
                    } else {
                        pn.right = Child::Node(idx);
                    }
                    self.nodes[tail].parent = Some(idx);
                }
                None => {
                    self.head = idx;
                }
            }
            self.tail = idx;
        }
        self.last_pushed = Token::Operator;
    }
    fn open_par(&mut self) {
        let node = Node::new(Some(self.tail));
        self.nodes.push(node);
        let idx = self.nodes.len() - 1;
        self.add_child(Child::Node(idx));
        self.tail = idx;
        self.openness += 1;
        self.last_pushed = Token::OpeningPar;
    }
    fn close_par(&mut self) {
        self.openness -= 1;
        if let Some(p) = self.nodes[self.tail].parent {
            self.tail = p;
        }
        self.last_pushed = Token::ClosingPar;
    }
    fn is_empty(&self) -> bool {
        self.atoms.is_empty() && self.nodes.len() == 1 && self.nodes[0].operator.is_none()
    }
}

/// the compiled tree
struct Compiled {
    atoms: Vec<Regex>,
    nodes: Vec<Node>,
    head: usize,
}

impl Compiled {
    fn eval_child(&self, child: Child, s: &str) -> Option<bool> {
        match child {
            Child::None => None,
            Child::Atom(i) => Some(self.atoms[i].is_match(s)),
            Child::Node(i) => self.eval_node(i, s),
        }
    }
    fn eval_node(&self, idx: usize, s: &str) -> Option<bool> {
        let node = &self.nodes[idx];
        let left = self.eval_child(node.left, s)?;
        match node.operator {
            None => Some(left),
            Some(op) => {
                // short circuits
                match op {
                    Op::And if !left => return Some(false),
                    Op::Or if left => return Some(true),
                    _ => {}
                }
                let right = self.eval_child(node.right, s);
                Some(match (op, right) {
                    (Op::And, Some(r)) => left && r,
                    (Op::Or, Some(r)) => left || r,
                    (Op::Not, None) => !left,
                    _ => crate::panic_like(
                        "src/filters/str_filter.rs:32:17",
                        "unexpected operator or operands",
                    ),
                })
            }
        }
    }
}

#[derive(Debug)]
pub struct StrFilter {
    pattern: String,
    /// when the pattern contains commas, it's a simple AND list
    and_list: Option<Vec<(bool, Regex)>>,
    tree: Option<Compiled>,
}

impl std::fmt::Debug for Compiled {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Compiled")
    }
}

fn regex(s: &str) -> Result<Regex, StrFilterError> {
    Regex::new(s).map_err(StrFilterError::InvalidRegex)
}

fn invalid(pattern: &str, msg: &str) -> StrFilterError {
    StrFilterError::InvalidPattern(pattern.to_string(), msg.to_string())
}

fn parse_expression(pattern: &str) -> Result<BeTree, StrFilterError> {
    let chars: Vec<char> = pattern.chars().collect();
    let mut tree = BeTree::new();
    for (i, &c) in chars.iter().enumerate() {
        let prev = if i > 0 { Some(chars[i - 1]) } else { None };
        let next = chars.get(i + 1).copied();
        match c {
            ' ' => {}
            '&' | '|' if next == Some(' ') => {
                if !tree.accepts_binary() {
                    return Err(invalid(pattern, &format!("unexpected '{}'", c)));
                }
                tree.push_binary(if c == '&' { Op::And } else { Op::Or });
            }
            '!' if tree.accepts_operand() => {
                tree.push_unary(Op::Not);
            }
            '(' if next == Some(' ') => {
                if !tree.accepts_operand() {
                    return Err(invalid(pattern, "unexpected opening parenthesis"));
                }
                tree.open_par();
            }
            ')' if prev == Some(' ') => {
                if tree.openness == 0 || !tree.accepts_binary() {
                    println!("expr: {:#?}", tree);
                    return Err(invalid(pattern, "unexpected closing parenthesis"));
                }
                tree.close_par();
            }
            _ => {
                tree.push_atom_char(c);
            }
        }
    }
    Ok(tree)
}

impl StrFilter {
    pub fn new(pattern: &str) -> Result<Self, StrFilterError> {
        if pattern.contains(',') {
            let mut list = Vec::new();
            for part in pattern.split(',') {
                let part = part.trim();
                if part.is_empty() {
                    return Err(invalid(pattern, "empty token"));
                }
                let (neg, re) = match part.strip_prefix('!') {
                    Some(rest) => (true, rest),
                    None => (false, part),
                };
                list.push((neg, regex(re)?));
            }
            return Ok(StrFilter { pattern: pattern.to_string(), and_list: Some(list), tree: None });
        }
        let tree = parse_expression(pattern)?;
        if tree.is_empty() {
            return Ok(StrFilter { pattern: pattern.to_string(), and_list: None, tree: None });
        }
        let mut atoms = Vec::new();
        for a in &tree.atoms {
            atoms.push(regex(a)?);
        }
        let compiled = Compiled { atoms, nodes: tree.nodes, head: tree.head };
        Ok(StrFilter { pattern: pattern.to_string(), and_list: None, tree: Some(compiled) })
    }

    pub fn pattern(&self) -> &str {
        &self.pattern
    }

    /// evaluate the filter; returns None when the expression has no result
    pub fn eval(&self, s: &str) -> Option<bool> {
        if let Some(list) = &self.and_list {
            return Some(list.iter().all(|(neg, re)| re.is_match(s) != *neg));
        }
        match &self.tree {
            Some(t) => t.eval_node(t.head, s),
            None => None,
        }
    }

    /// whether the string passes the filter (printing a message when the
    /// expression can't be evaluated)
    pub fn contains(&self, s: &str) -> bool {
        match self.eval(s) {
            Some(b) => b,
            None => {
                println!("unexpected lack of expr result on {:?}", s);
                false
            }
        }
    }
}
