import re, subprocess, sys, glob
def parse(logf):
    lines=[]
    for l in open(logf, errors='replace'):
        m=re.match(r'(\S+) \S+ \S+ \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]*\] "([^"]*)" (\d+) (\d+) "([^"]*)"', l)
        if not m: continue
        day=int(m.group(2)); mon=m.group(3); req=m.group(8); by=int(m.group(10)); ref=m.group(11); ip=m.group(1); st=int(m.group(9))
        parts=req.split(' '); path=parts[1].split('?')[0] if len(parts)>1 else req
        lines.append(((mon,day),path,by,ref,ip,st))
    # date indexes by consecutive grouping
    dates=[]; idx=[]
    for l in lines:
        if not dates or dates[-1]!=l[0]: dates.append(l[0])
        idx.append(len(dates)-1)
    return lines, idx, len(dates)
def arrows_for(formula, h, tot, nd, hits):
    s=max(0,nd-20); wh=h[s:]; wt=tot[s:]
    rc=sum(wh[:-2]); tc=sum(wh[-2:]); rt=sum(wt[:-2]); tt=sum(wt[-2:])
    v=formula(rc,tc,rt,tt)
    pm=int(1000*v); a=abs(pm)
    n=3 if a>900 else 2 if a>500 else 1 if a>200 else 0
    if hits<10: n=0
    return -n if pm<0 else n
def fA(rc,tc,rt,tt):
    rs=rc/rt if rt else 0; ts=tc/tt if tt else 0
    return (ts-rs)/(ts+rs) if ts+rs>0 else 0
def fB(rc,tc,rt,tt):
    rs=(rc+1)/rt if rt else 0; ts=(tc+1)/tt if tt else 0
    return (ts-rs)/(ts+rs) if ts+rs>0 else 0
def fC(rc,tc,rt,tt):
    rs=(rc+1)/(rt+1); ts=(tc+1)/(tt+1)
    return (ts-rs)/(ts+rs)
def check(logf, formulas):
    lines, idx, nd = parse(logf)
    if nd<4: return None
    tot=[0]*nd
    for i in idx: tot[i]+=1
    paths={}
    for l,i in zip(lines,idx):
        paths.setdefault(l[1],[0]*nd); paths[l[1]][i]+=1
    out=subprocess.run(['/workspace/executable',logf,'-f','p','-l','7','-a'],capture_output=True,text=True).stdout
    obs={}
    for l in out.splitlines():
        if l.startswith('│') and '│' in l[1:]:
            cs=l.strip('│').split('│')
            if cs[1].strip() in paths: obs[cs[1].strip()]=cs[-1].count('➚')-cs[-1].count('➘')
    res={}
    for name,f in formulas.items():
        bad=0; n=0
        for p,h in paths.items():
            if p not in obs: continue
            n+=1
            a=arrows_for(f,h,tot,nd,sum(h))
            if a!=obs[p]: bad+=1
        res[name]=(bad,n)
    return res
formulas={'A':fA,'B':fB,'C':fC}
for logf in sys.argv[1:]:
    r=check(logf, formulas)
    if r: print(logf, r)
